//! Cutechess-shaped annotated PGN output -- `{<score>/<depth> <time>s}` per move for a
//! fitness-selection match, matching cutechess-cli's own comment format and field order exactly
//! (`chessgame.cpp`'s `evalString`), or bare `{<score>}` for self-play (`format_game`'s own
//! `include_depth_and_time` flag), decided directly with the developer. SAN move text itself is
//! generated by `shakmaty`
//! (`San`/`SanPlus`), not hand-written: disambiguation, captures, castling, promotion, and
//! check/mate suffixes are exactly the kind of chess-notation logic worth leaning on an
//! existing library for, per the developer's own explicit call, rather than rederiving it here.
//! `shakmaty` only ever replays UCI move strings Fattorini's own `format_move`/`parse_move` already
//! produced and validated as legal against Fattorini's own `legal_moves` -- it is never asked to
//! judge legality itself, the same "lean on a crate for notation only, never for chess
//! semantics" line the `pgn-replay` crate's own `try_resolve_san` already draws on the reading side.
//!
//! Used by every mode of `arena`: the matches and the gate, and self-play.

use std::fmt::Write as FmtWrite;
use std::fs::OpenOptions;
use std::io::Write as IoWrite;
use std::path::Path;
use std::str::FromStr;
use std::time::Duration;

use shakmaty::fen::Fen;
use shakmaty::san::SanPlus;
use shakmaty::uci::UciMove;
use shakmaty::{CastlingMode, Chess, Color, Position};

/// One already-played ply's own move and annotation -- decoupled from `player::SearchReport`
/// so the PGN writer doesn't need to know about UCI client internals.
pub struct MoveAnnotation {
    pub uci: String,
    pub score_cp: Option<i32>,
    pub mate_in: Option<i32>,
    pub depth: Option<u32>,
    pub time: Duration,
    /// Self-play's best move of the position before this ply, in UCI, written after the score
    /// (`{0.31 g8f6}`) as the training label of a move head; `None` in matches, which keep
    /// cutechess-cli's shape.
    pub best: Option<String>,
}

/// Why a game ended -- written into the PGN itself as a `[Termination "..."]` tag (the real PGN
/// standard's own supplemental-tag vocabulary is a small fixed set, `"normal"`/`"abandoned"`/
/// `"time forfeit"`/etc., not specific enough to say *which* rule actually applied; this reuses
/// the tag's name, a syntactically valid PGN tag either way, with values specific enough to
/// actually answer "why did this game end a draw" without hand-tracing the movetext -- decided
/// directly with the developer, after a real self-play draw with a flat `0.00` score throughout
/// turned out to be genuine twofold repetition, undiagnosable from the PGN alone until this
/// existed). Lives here, not `results_db.rs` (where it used to be defined): self-play (then its own binary) has no
/// database at all and must not depend on `rusqlite`, but does need this same type to annotate its
/// own PGN, so the canonical definition moved to this shared, dependency-light module instead
/// (`results_db.rs` now imports it from here). Not every variant is reachable from every caller --
/// self-play only ever produces `Checkmate`/`Stalemate`/`InsufficientMaterial`/`FiftyMoveRule`/`Repetition` (no
/// adjudication of any kind, `self_play.rs`'s own `play_one_game` doc comment), while the
/// fitness-selection match runner can also produce `TimeForfeit`/`Crashed`/`IllegalMove` -- one
/// shared enum regardless, rather than two overlapping ones to keep in sync by hand.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Termination {
    Checkmate,
    Stalemate,
    /// Neither side can mate (`search::is_insufficient_material`): a dead position, drawn.
    InsufficientMaterial,
    Repetition,
    FiftyMoveRule,
    TimeForfeit,
    Crashed,
    IllegalMove,
    /// Early stop's win rule (`game::Adjudicator`): both sides' scores agreed on a winner for long
    /// enough. Never outside a tune, whose games alone end early.
    AdjudicatedWin,
    /// Early stop's draw rule: both sides' scores stayed near zero for long enough, late enough.
    AdjudicatedDraw,
    /// Early stop's tablebase rule: the tables' result under the fifty-move rule.
    AdjudicatedTablebase,
}

impl Termination {
    pub fn as_str(self) -> &'static str {
        match self {
            Termination::Checkmate => "checkmate",
            Termination::Stalemate => "stalemate",
            Termination::InsufficientMaterial => "insufficient-material",
            Termination::Repetition => "repetition",
            Termination::FiftyMoveRule => "fifty-move",
            Termination::TimeForfeit => "time-forfeit",
            Termination::Crashed => "crashed",
            Termination::IllegalMove => "illegal-move",
            Termination::AdjudicatedWin => "adjudication-win",
            Termination::AdjudicatedDraw => "adjudication-draw",
            Termination::AdjudicatedTablebase => "adjudication-tablebase",
        }
    }
}

pub struct GameHeaders {
    pub event: String,
    pub round: u32,
    pub white: String,
    pub black: String,
    /// The game's own starting position -- an opening book FEN, not necessarily the standard
    /// starting position (see `book.rs`). Always written out as `[FEN]`/`[SetUp]` tags, so the
    /// movetext below is self-contained and correctly numbered even when it doesn't start with
    /// White's move 1.
    pub starting_fen: String,
}

/// Formats one game's own headers plus movetext block, ready to append to a `.pgn` file.
/// `result` is the standard PGN result token (`"1-0"`, `"0-1"`, `"1/2-1/2"`, or `"*"`).
/// `termination` (`Termination`'s own doc comment covers why it's a project-specific value, not
/// the real PGN standard's own generic `"normal"`/`"abandoned"`/etc.) becomes the `[Termination]`
/// tag, written right after `[Result]`. `include_depth_and_time` selects the per-move comment's own shape: the full cutechess-style
/// `{<score>/<depth> <time>s}` for a fitness-selection match (where depth/remaining clock are
/// genuinely informative, comparing two different engines), or bare `{<score>}` for self-play
/// (fixed search depth, no real clock -- just the wall time one search happened to take, neither
/// worth carrying into training data).
pub fn format_game(
    headers: &GameHeaders, moves: &[MoveAnnotation], result: &str, termination: Termination, include_depth_and_time: bool,
) -> String {
    let mut text = String::new();
    writeln!(text, "[Event \"{}\"]", headers.event).unwrap();
    writeln!(text, "[Round \"{}\"]", headers.round).unwrap();
    writeln!(text, "[White \"{}\"]", headers.white).unwrap();
    writeln!(text, "[Black \"{}\"]", headers.black).unwrap();
    writeln!(text, "[Result \"{result}\"]").unwrap();
    writeln!(text, "[Termination \"{}\"]", termination.as_str()).unwrap();
    writeln!(text, "[FEN \"{}\"]", headers.starting_fen).unwrap();
    writeln!(text, "[SetUp \"1\"]").unwrap();
    text.push('\n');

    let fen = Fen::from_str(&headers.starting_fen)
        .unwrap_or_else(|error| panic!("PGN writer received an invalid starting FEN {:?}: {error}", headers.starting_fen));
    let mut position: Chess = fen
        .into_position(CastlingMode::Standard)
        .unwrap_or_else(|error| panic!("PGN writer received an illegal starting FEN {:?}: {error}", headers.starting_fen));

    for (ply_index, annotation) in moves.iter().enumerate() {
        let uci_move: UciMove = annotation
            .uci
            .parse()
            .unwrap_or_else(|error| panic!("PGN writer received an invalid UCI move string {:?}: {error}", annotation.uci));
        let shakmaty_move = uci_move
            .to_move(&position)
            .unwrap_or_else(|error| panic!("PGN writer received an illegal move {:?}: {error}", annotation.uci));
        let san = SanPlus::from_move(position.clone(), shakmaty_move);

        let white_to_move = position.turn() == Color::White;
        if white_to_move {
            write!(text, "{}. ", position.fullmoves()).unwrap();
        } else if ply_index == 0 {
            // The opening itself starts mid-move, with Black to move first -- standard PGN
            // convention marks that with an ellipsis instead of silently omitting White's
            // (nonexistent, at this starting position) move.
            write!(text, "{}... ", position.fullmoves()).unwrap();
        }
        write!(text, "{san} {} ", annotate(annotation, include_depth_and_time)).unwrap();

        position = position
            .play(shakmaty_move)
            .unwrap_or_else(|error| panic!("PGN writer's own position rejected an already-validated move: {error}"));
    }
    writeln!(text, "{result}").unwrap();
    text.push('\n');
    text
}

/// `{<score>/<depth> <time>s}` when `include_depth_and_time` (matching cutechess-cli's own
/// `evalString` (`chessgame.cpp`) field order exactly: score first, decimal pawns or `#N` for a
/// mate-in-`N` score, then `/` and the depth if one was reported, then the elapsed time with a
/// trailing `s`), or bare `{<score>}` otherwise, followed by ` <best>` when the annotation has a
/// best move.
fn annotate(annotation: &MoveAnnotation, include_depth_and_time: bool) -> String {
    let mut text = String::from("{");
    match (annotation.score_cp, annotation.mate_in) {
        (Some(cp), _) => write!(text, "{:.2}", cp as f64 / 100.0).unwrap(),
        (None, Some(mate)) => write!(text, "#{mate}").unwrap(),
        (None, None) => {}
    }
    if let Some(best) = &annotation.best {
        write!(text, " {best}").unwrap();
    }
    if include_depth_and_time {
        if let Some(depth) = annotation.depth {
            write!(text, "/{depth}").unwrap();
        }
        write!(text, " {:.1}s", annotation.time.as_secs_f64()).unwrap();
    }
    text.push('}');
    text
}

/// Appends `game_text` to `path`, creating both the file and its parent directory if this is
/// the first game written: the target directory may not exist yet on a fresh checkout.
pub fn append_to_file(path: &str, game_text: &str) {
    if let Some(parent) = Path::new(path).parent() {
        std::fs::create_dir_all(parent).unwrap_or_else(|error| panic!("failed to create directory {}: {error}", parent.display()));
    }
    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .unwrap_or_else(|error| panic!("failed to open {path}: {error}"));
    file.write_all(game_text.as_bytes())
        .unwrap_or_else(|error| panic!("failed to write {path}: {error}"));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn termination_as_str_covers_every_variant_with_a_distinct_lowercase_value() {
        let variants = [
            Termination::Checkmate,
            Termination::Stalemate,
            Termination::InsufficientMaterial,
            Termination::Repetition,
            Termination::FiftyMoveRule,
            Termination::TimeForfeit,
            Termination::Crashed,
            Termination::IllegalMove,
            Termination::AdjudicatedWin,
            Termination::AdjudicatedDraw,
            Termination::AdjudicatedTablebase,
        ];
        let strings: Vec<&str> = variants.iter().map(|&t| t.as_str()).collect();
        for s in &strings {
            assert_eq!(*s, s.to_lowercase());
        }
        let mut deduped = strings.clone();
        deduped.sort();
        deduped.dedup();
        assert_eq!(deduped.len(), strings.len(), "every variant must map to its own distinct string: {strings:?}");
    }

    #[test]
    fn format_game_writes_a_termination_tag_right_after_result() {
        let headers = GameHeaders {
            event: "fattorini self-play".to_string(),
            round: 0,
            white: "fattorini".to_string(),
            black: "fattorini".to_string(),
            starting_fen: "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1".to_string(),
        };
        let moves = [MoveAnnotation {
            uci: "e2e4".to_string(),
            score_cp: Some(0),
            mate_in: None,
            depth: Some(9),
            time: Duration::from_secs(0),
            best: Some("d2d4".to_string()),
        }];

        let text = format_game(&headers, &moves, "1/2-1/2", Termination::Repetition, false);

        let lines: Vec<&str> = text.lines().collect();
        let result_index = lines.iter().position(|line| *line == "[Result \"1/2-1/2\"]").expect("no [Result] tag found");
        assert_eq!(lines[result_index + 1], "[Termination \"repetition\"]");
        assert!(text.contains("1. e4 {0.00 d2d4} 1/2-1/2"), "the best move follows the score: {text}");
    }
}
